package palindrome

import (
	"fmt"
	"strconv"
)

// Product represents a palindromic number along with the pairs of factors
// (within the given range) whose product is that number.
type Product struct {
	Product        int
	Factorizations [][2]int
}

// Products returns the smallest and largest palindromic products of two
// factors within the inclusive range [fmin, fmax], along with all factor
// pairs for each. It returns an error if fmin > fmax or if no palindromic
// product exists in the range.
func Products(fmin, fmax int) (Product, Product, error) {
	if fmin > fmax {
		return Product{}, Product{}, fmt.Errorf("fmin > fmax")
	}

	var minP, maxP Product
	minFound, maxFound := false, false

	for i := fmin; i <= fmax; i++ {
		for j := i; j <= fmax; j++ {
			p := i * j
			if !isPalindrome(p) {
				continue
			}
			if !minFound || p < minP.Product {
				minP = Product{p, [][2]int{{i, j}}}
				minFound = true
			} else if p == minP.Product {
				minP.Factorizations = append(minP.Factorizations, [2]int{i, j})
			}
			if !maxFound || p > maxP.Product {
				maxP = Product{p, [][2]int{{i, j}}}
				maxFound = true
			} else if p == maxP.Product {
				maxP.Factorizations = append(maxP.Factorizations, [2]int{i, j})
			}
		}
	}

	if !minFound {
		return Product{}, Product{}, fmt.Errorf("no palindromes found in the range %d-%d", fmin, fmax)
	}

	return minP, maxP, nil
}

// isPalindrome reports whether n reads the same forwards and backwards.
// Negative numbers (whose string form contains '-') are not palindromes.
func isPalindrome(n int) bool {
	s := strconv.Itoa(n)
	for i, j := 0, len(s)-1; i < j; i, j = i+1, j-1 {
		if s[i] != s[j] {
			return false
		}
	}
	return true
}

